def wrap(text, width, indent=""):
    """Wrap paragraphs independently, with a hanging indent on continuations."""
    if not isinstance(width, int) or isinstance(width, bool) or width < 1:
        raise ValueError("width must be a positive integer")
    if not isinstance(indent, str) or len(indent) >= width or "\n" in indent:
        raise ValueError("indent must be a single-line string shorter than width")

    lines = []
    for paragraph in text.split("\n"):
        line = ""
        for word in paragraph.split():
            if line:
                if len(line) + 1 + len(word) <= width:
                    line += " " + word
                    continue
                lines.append(line)
                line = indent

            start = 0
            capacity = width - len(line)
            while len(word) - start > capacity:
                lines.append(line + word[start:start + capacity])
                start += capacity
                line = indent
                capacity = width - len(indent)
            line += word[start:]
        lines.append(line)
    return lines
